parameters.jsCode:
const err = $input.item.json;
const timestamp = new Date().toISOString();
const incident = {
  incident_id: 'INC-' + Date.now(),
  failed_at: timestamp,
  workflow_id: err.workflow ? err.workflow.id : 'unknown',
  workflow_name: err.workflow ? err.workflow.name : 'Invoice Processing',
  execution_id: err.execution ? err.execution.id : 'unknown',
  failed_node: err.execution ? err.execution.lastNodeExecuted : 'unknown',
  error_message: err.execution && err.execution.error ? err.execution.error.message : 'Unspecified execution error',
  severity: 'HIGH',
  requires_devops_alert: true
};
return { json: incident };

